  "NativeProof.cs": "using System.Reflection;
using System.Reflection.Emit;
using System.Runtime.CompilerServices;
using System.Text.Json;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using HarmonyLib;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Extensions;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;

namespace CombatSolver;

internal static class SortMemoNativeProof
{
    private static int _patchCalls;
    private static CombatPredictionSimulator? _patchedBranch;
    private static Player? _patchedPlayer;
    private static bool _throw;
    private static readonly InvalidOperationException Injected = new("native-sort-memo-injected");
    private static void PatchedCompare()
    {
        _patchCalls++;
        _patchedBranch!.State.GetCreature(_patchedPlayer!.Creature).CurrentHp--;
        if (_throw) throw Injected;
    }

    internal static string Verify(CombatState live, CombatPredictionSimulator parent,
        Player player, Func<CombatPredictionSimulator, string> stamp)
    {
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        string parentBefore = stamp(parent);
        NativeCardSortProfile rules = NativeCardSortProfile.Capture();
        if (!rules.Enabled || rules.RegisteredTypeCount != 603)
            throw new InvalidOperationException("Audited native sort rules not exercised.");
        ProjectedShuffleSortMemo memo = new(rules);
        var keyBuffer = new SnapshotListBuffer<ProjectedShuffleSortMemo.SortKey>();
        var sortBuffer = new SnapshotListBuffer<ProjectedShuffleSortMemo.SortItem>();
        var sourceBuffer = new SnapshotListBuffer<PredictedCard>();
        List<PredictedCard> all = ModelDb.All.OfType<CardModel>()
            .Where(c => c.GetType().Assembly == typeof(CardModel).Assembly)
            .Select(c => new PredictedCard(c)).ToList();
        var first = PredictedCard.Create(ModelDb.Card<StrikeIronclad>(), player);
        var second = PredictedCard.Create(ModelDb.Card<StrikeIronclad>(), player);
        first.MutablePreview.BaseReplayCount = 1;
        second.MutablePreview.BaseReplayCount = 2;
        int cases = 0, hits = 0, bypasses = 0;

        void Check(List<PredictedCard> input, ProjectedShuffleSortMemo cache,
            SnapshotListBuffer<ProjectedShuffleSortMemo.SortKey> keys,
            SnapshotListBuffer<ProjectedShuffleSortMemo.SortItem> items,
            SnapshotListBuffer<PredictedCard> sources, bool admitted, bool? expectedHit = null)
        {
            var native = new List<PredictedCard>(input);
            var candidate = new List<PredictedCard>(input);
            var a = parent.Rng.ShuffleState.ToRng();
            var b = parent.Rng.ShuffleState.ToRng();
            native.StableShuffle(a);
            bool accepted = cache.TrySort(candidate, keys, items, sources, out bool hit);
            if (accepted != admitted || expectedHit is { } expected && hit != expected)
                throw new InvalidOperationException("Sort memo eligibility/hit gate differs.");
            if (!accepted) candidate.Sort();
            candidate.UnstableShuffle(b);
            if (!native.SequenceEqual(candidate, ReferenceEqualityComparer.Instance)
                || a.CaptureState() != b.CaptureState())
                throw new InvalidOperationException("Cold/hot native ordering or complete RNG differs.");
            cases++; if (hit) hits++; if (!accepted) bypasses++;
        }
        void Pair(List<PredictedCard> input)
        {
            ProjectedShuffleSortMemo isolated = new(rules);
            Check(input, isolated, keyBuffer, sortBuffer, sourceBuffer, true, false);
            Check(input, isolated, keyBuffer, sortBuffer, sourceBuffer, true, true);
        }
        Pair(all);
        Pair([second, first, first, second]);
        Pair([first, second, first, second]);
        Random random = new(20261006);
        foreach (int count in new[] { 0, 1, 2, 3, 8, 16, 17, 32, 63, 128, 396, 4096 })
            Pair(Enumerable.Range(0, count).Select(_ => all[random.Next(all.Count)]).ToList());
        Check(Enumerable.Range(0, 4097).Select(_ => all[random.Next(all.Count)]).ToList(),
            memo, keyBuffer, sortBuffer, sourceBuffer, false);
        Check([second, first], new(NativeCardSortProfile.CaptureForModule(Guid.Empty)),
            keyBuffer, sortBuffer, sourceBuffer, false);

        var unknown = new PredictedCard(Unknown());
        List<PredictedCard> unknownInput = [first, second, unknown], unchanged = [.. unknownInput];
        if (memo.TrySort(unknownInput, keyBuffer, sortBuffer, sourceBuffer, out _)
            || !unknownInput.SequenceEqual(unchanged, ReferenceEqualityComparer.Instance))
            throw new InvalidOperationException("Unknown source read/sorted before rejection.");

        CombatPredictionSimulator fork;
        using (SimulationNotificationIsolation.Enter())
        {
            fork = parent.Fork();
            var card = fork.State.GetPlayerCombatState(player).Hand.Cards[0];
            List<PredictedCard> input = [card, second, first];
            Pair(input);
            card.MutablePreview.UpgradeInternal();
            Pair(input);
        }
        string forkBefore = stamp(fork);
        int parallelCases = 0;
        Parallel.For(0, 16, index =>
        {
            using IDisposable isolation = SimulationNotificationIsolation.Enter();
            CombatPredictionSimulator child;
            lock (parent) child = parent.Fork();
            string before = stamp(child);
            var keys = new SnapshotListBuffer<ProjectedShuffleSortMemo.SortKey>();
            var items = new SnapshotListBuffer<ProjectedShuffleSortMemo.SortItem>();
            var sources = new SnapshotListBuffer<PredictedCard>();
            List<PredictedCard> input = Enumerable.Range(0, 128)
                .Select(i => all[(i * 31 + index) % all.Count]).ToList();
            List<PredictedCard> a = [.. input], b = [.. input];
            a.Sort();
            if (!memo.TrySort(b, keys, items, sources, out _)
                || !a.SequenceEqual(b, ReferenceEqualityComparer.Instance))
                throw new InvalidOperationException("Concurrent publication/permutation differs.");
            if (before != stamp(child)) throw new InvalidOperationException("Sort changed fork state/RNG/history.");
            Interlocked.Increment(ref parallelCases);
        });

        var target = typeof(CardModel).GetMethod(nameof(CardModel.CompareTo), [typeof(AbstractModel)])!;
        var prefix = typeof(SortMemoNativeProof).GetMethod(nameof(PatchedCompare), BindingFlags.Static | BindingFlags.NonPublic)!;
        Harmony harmony = new("CombatSolver.Tests.SortMemoNative");
        try
        {
            harmony.Patch(target, prefix: new HarmonyMethod(prefix));
            var rejected = new ProjectedShuffleSortMemo(NativeCardSortProfile.Capture());
            (int Calls, string State, Exception? Error) Execute(bool useMemo, bool throwing)
            {
                using IDisposable isolation = SimulationNotificationIsolation.Enter();
                _patchedBranch = parent.Fork(); _patchedPlayer = player;
                _patchCalls = 0; _throw = throwing;
                List<PredictedCard> cards = [second, first, first, second];
                Exception? error = null;
                try
                {
                    if (!useMemo || !rejected.TrySort(cards, keyBuffer, sortBuffer, sourceBuffer, out _))
                        cards.Sort();
                }
                catch (InvalidOperationException e) { error = e; }
                return (_patchCalls, stamp(_patchedBranch), error);
            }
            foreach (bool throwing in new[] { false, true })
            {
                var a = Execute(false, throwing); var b = Execute(true, throwing);
                if (a.Calls == 0 || a.Calls != b.Calls || a.State != b.State
                    || (a.Error is null) != (b.Error is null)
                    || throwing && (a.Error?.InnerException != Injected || b.Error?.InnerException != Injected))
                    throw new InvalidOperationException("Patched native fallback effects/exception differ.");
            }
        }
        finally { harmony.Unpatch(target, prefix); _patchedBranch = null; _patchedPlayer = null; }
        if (stamp(parent) != parentBefore || stamp(fork) != forkBefore
            || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
            throw new InvalidOperationException("Sort memo changed parent/live/full state.");
        return "SortMemoEvidence:" + JsonSerializer.Serialize(new { cases, hits, bypasses,
            parallelCases, registeredTypes = rules.RegisteredTypeCount,
            scope = "Cold/hot permutations; current upgrade; unknown source/module; callback side effects/exceptions; complete RNG and branch/parent/live state." });
    }

    private static CardModel Unknown()
    {
        var assembly = AssemblyBuilder.DefineDynamicAssembly(new AssemblyName("CombatSolver.Tests.SortMemo.Unknown"), AssemblyBuilderAccess.RunAndCollect);
        var type = assembly.DefineDynamicModule("Probe").DefineType("UnknownCard", TypeAttributes.Public | TypeAttributes.Sealed, typeof(CardModel));
        var constructor = type.DefineConstructor(MethodAttributes.Public, CallingConventions.Standard, Type.EmptyTypes);
        var il = constructor.GetILGenerator(); il.Emit(OpCodes.Ldnull); il.Emit(OpCodes.Throw);
        return (CardModel)RuntimeHelpers.GetUninitializedObject(type.CreateType()!);
    }
}
