    private const int SlotCount = 1024;
    private const int MaximumCards = 4096;
    private readonly Entry?[] _slots = new Entry?[SlotCount];
    internal readonly record struct SortKey(int Rank, int Upgrade);
    internal readonly record struct SortItem(PredictedCard Card, SortKey Key, int SourceIndex)
        : IComparable<SortItem>
    {
        public int CompareTo(SortItem other)
        {
            int order = Key.Rank.CompareTo(other.Key.Rank);
            return order != 0 ? order : Key.Upgrade.CompareTo(other.Key.Upgrade);
        }
    }
    private sealed record Entry(SortKey[] Keys, int[] Order);

    internal bool TrySort(List<PredictedCard> cards,
        SnapshotListBuffer<SortKey> keyBuffer,
        SnapshotListBuffer<SortItem> sortBuffer,
        SnapshotListBuffer<PredictedCard> sourceBuffer,
        out bool cacheHit)
    {
        cacheHit = false;
        if (!profile.Enabled || cards.Count > MaximumCards)
            return false;
        using var keyLease = keyBuffer.Rent();
        List<SortKey> keys = keyLease.Items;
        keys.EnsureCapacity(cards.Count);
        ulong hash = (ulong)cards.Count;
        foreach (PredictedCard card in cards)
        {
            if (card is null || !profile.TryGetKey(card, out int rank, out int upgrade))
                return false;
            keys.Add(new(rank, upgrade));
            hash = unchecked((hash ^ (uint)rank) * 1099511628211UL);
            hash = unchecked((hash ^ (uint)upgrade) * 1099511628211UL);
        }
        int slot = (int)(hash & (SlotCount - 1));
        Entry? entry = Volatile.Read(ref _slots[slot]);
        if (entry is not null && SameKeys(entry.Keys, keys))
        {
            using var sourceLease = sourceBuffer.Rent();
            List<PredictedCard> source = sourceLease.Items;
            source.AddRange(cards);
            for (int index = 0; index < cards.Count; index++)
                cards[index] = source[entry.Order[index]];
            cacheHit = true;
            return true;
        }
        using var sortLease = sortBuffer.Rent();
        List<SortItem> sorted = sortLease.Items;
        sorted.EnsureCapacity(cards.Count);
        for (int index = 0; index < cards.Count; index++)
            sorted.Add(new(cards[index], keys[index], index));
        sorted.Sort();
        int[] order = new int[cards.Count];
        for (int index = 0; index < cards.Count; index++)
        {
            cards[index] = sorted[index].Card;
            order[index] = sorted[index].SourceIndex;
        }
        Volatile.Write(ref _slots[slot], new(keys.ToArray(), order));
        return true;
    }

    private static bool SameKeys(SortKey[] saved, List<SortKey> current)
    {
        if (saved.Length != current.Count)
            return false;
        for (int index = 0; index < saved.Length; index++)
            if (saved[index] != current[index])
                return false;
        return true;
    }
}
